<?php require_once __DIR__.'/../includes/functions.php';$sent=false;$error='';if($_SERVER['REQUEST_METHOD']==='POST'){try{$s=db()->prepare('INSERT INTO service_requests(name,email,phone,service,message) VALUES(?,?,?,?,?)');$s->execute([trim($_POST['name']),trim($_POST['email']),trim($_POST['phone']),trim($_POST['service']),trim($_POST['message'])]);$sent=true;}catch(Throwable $e){$error='Please install the platform database before submitting.';}}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Business Technology | Plateau Digital</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><?php include __DIR__.'/../includes/public_header.php';?><main class="section page-section"><span class="eyebrow">Technology that moves business forward</span><h1>Business Technology</h1><p>Request support with websites, e-commerce, business software, branding and digital transformation.</p><?php if($sent):?><div class="alert success">Thank you. Your request has been received.</div><?php elseif($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><form class="request-form" method="post"><label>Your name<input name="name" required></label><label>Email<input type="email" name="email"></label><label>Phone number<input name="phone"></label><label>Service needed<select name="service" required><option value="">Choose a service</option><option>Website development</option><option>E-commerce solution</option><option>Business management software</option><option>Branding and graphics</option><option>Digital transformation consultation</option><option>Other</option></select></label><label>Tell us about your needs<textarea name="message" rows="5" required></textarea></label><button class="btn">Send service request</button></form></main><?php include __DIR__.'/../includes/public_footer.php';?></body></html>